diff --git a/src/httpserver.h b/src/httpserver.h
index 26d904db23..f4d83d4047 100644
--- a/src/httpserver.h
+++ b/src/httpserver.h
@@ -625,6 +625,12 @@ private:
     //! `m_keep_alive=true` can be overridden `by HTTPServer.m_disconnect_all_clients` (we disconnect).
     std::atomic_bool m_keep_alive{false};

+    //! A reply that closes the connection (e.g. to a "Connection: close" request)
+    //! has been queued. No further requests are read from this client, whether
+    //! or not that reply has been flushed yet. Set by a worker thread and checked
+    //! in the HTTPServer I/O loop; never reset.
+    std::atomic_bool m_closing{false};
+
     //! Flag this client for disconnection on next loop.
     //! Either we have encountered a permanent error, or both sides of the socket are done
     //! with the connection, e.g. our reply to a "Connection: close" request has been sent.
diff --git a/src/httpserver.cpp b/src/httpserver.cpp
index dc2b8e8310..a43d9bee8a 100644
--- a/src/httpserver.cpp
+++ b/src/httpserver.cpp
@@ -589,8 +589,11 @@ void HTTPRequest::WriteReply(HTTPStatusCode status, std::span<const std::byte> r
         res.headers.Write("Content-Type", "text/html; charset=ISO-8859-1");
     }

+    // RFC 9112 section 6.1: the connection must be closed after responding to
+    // a request that has both Content-Length and Transfer-Encoding.
+    const bool conflicting_framing{m_headers.FindFirst("Content-Length") && m_headers.FindFirst("Transfer-Encoding")};
     auto connection_header{m_headers.FindFirst("Connection")};
-    if (connection_header && ToLower(connection_header.value()) == "close") {
+    if (conflicting_framing || (connection_header && ToLower(connection_header.value()) == "close")) {
         // Might not exist already but we need to replace it, not append to it
         res.headers.RemoveAll("Connection");

@@ -606,6 +609,7 @@ void HTTPRequest::WriteReply(HTTPStatusCode status, std::span<const std::byte> r
 void HTTPRemoteClient::Send(const HTTPResponse& res, std::span<const std::byte> reply_body, bool keep_alive)
 {
     m_keep_alive = keep_alive;
+    if (!keep_alive) m_closing = true;

     // Serialize the response headers
     const std::string headers{res.StringifyHeaders()};
@@ -1089,6 +1093,11 @@ std::unique_ptr<HTTPRequest> HTTPRemoteClient::TryReadRequest(const std::shared_
     // loop iteration.
     if (client->m_req_busy) return nullptr;

+    // Once a reply that closes the connection has been queued, or the client
+    // has been flagged for disconnection, no further requests are processed
+    // (RFC 9112 section 9.6), even if they are already in the receive buffer.
+    if (client->m_closing || client->m_disconnect) return nullptr;
+
     if (!client->m_req) {
         client->m_req = std::make_unique<HTTPRequest>(client);
     }
diff --git a/test/functional/interface_http.py b/test/functional/interface_http.py
index 61bb30bbe7..6f2c7ab2b6 100755
--- a/test/functional/interface_http.py
+++ b/test/functional/interface_http.py
@@ -563,11 +563,35 @@ class HTTPBasicsTest (BitcoinTestFramework):
             f"Transfer-Encoding: chunked\r\n"
             f"\r\n"
         ).encode("ascii") + chunk_body
-        conn.send_raw(raw)
-        response = conn.recv_raw().decode()
+        # A second request with a visible side effect is sent in the same write,
+        # so it is already in the receive buffer when the first reply is queued.
+        # https://www.rfc-editor.org/rfc/rfc9112#section-9.6
+        # The server must not process it after sending a reply that closes the connection.
+        body2 = b'{"method":"setnetworkactive","params":[false]}'
+        raw2 = (
+            f"POST / HTTP/1.1\r\n"
+            f"Host: {conn.url.hostname}\r\n"
+            f"Authorization: Basic {str_to_b64str(conn.authpair)}\r\n"
+            f"Content-Length: {len(body2)}\r\n"
+            f"\r\n"
+        ).encode("ascii") + body2
+        conn.send_raw(raw + raw2)
+        # Read until EOF: the server closes the connection after its reply.
+        response = b""
+        while True:
+            chunk = conn.recv_raw()
+            if not chunk:
+                break
+            response += chunk
+        response = response.decode()
+        assert_equal(response.count("HTTP/1.1"), 1)
         assert "HTTP/1.1 200 OK" in response
         count = self.node.getblockcount()
         assert f'"result":{count}' in response
+        # https://www.rfc-editor.org/rfc/rfc9112#section-6.1
+        # The server must close the connection after responding.
+        assert "Connection: close" in response
+        assert_equal(self.node.getnetworkinfo()["networkactive"], True)


     def check_duplicate_content_length(self):
diff --git a/src/test/httpserver_tests.cpp b/src/test/httpserver_tests.cpp
index 2ac63949fb..c9d151be00 100644
--- a/src/test/httpserver_tests.cpp
+++ b/src/test/httpserver_tests.cpp
@@ -518,8 +518,11 @@ BOOST_AUTO_TEST_CASE(http_request_state_tests)
         std::shared_ptr<DummyClient> client{std::make_shared<DummyClient>()};
         BOOST_CHECK(!client->GetRequest());

+        // keep-alive, otherwise the reply to the first request closes the
+        // connection and the second request is not read
         client->Receive("POST / HTTP/1.0\n"
                         "Host: 127.0.0.1\n"
+                        "Connection: keep-alive\n"
                         "Content-Length: 10\n\n"
                         "I miss");
         BOOST_CHECK(!HTTPRemoteClient::TryReadRequest(client));
@@ -549,6 +552,69 @@ BOOST_AUTO_TEST_CASE(http_request_state_tests)
         // Buffer is cleared
         BOOST_CHECK_EQUAL(client->GetRecvBuffer().size(), 0);
     }
+    {
+        // A request pipelined behind a request whose reply closes the
+        // connection is not read once that reply has been sent
+        std::shared_ptr<DummyClient> client{std::make_shared<DummyClient>()};
+        BOOST_CHECK(!client->GetRequest());
+
+        client->Receive("GET / HTTP/1.0\n\n"
+                        "GET /endpoint HTTP/1.0\n\n");
+        auto req{HTTPRemoteClient::TryReadRequest(client)};
+        BOOST_REQUIRE(req);
+        BOOST_CHECK_EQUAL(req->GetState(), Complete);
+        BOOST_CHECK_EQUAL(req->GetURI(), "/");
+        // Second request sitting in buffer
+        BOOST_CHECK_EQUAL(client->GetRecvBuffer().size(), 24);
+
+        // HTTP/1.0 without keep-alive: sending the reply flags the client for disconnection
+        req->WriteReply(HTTP_OK, "");
+
+        // The pipelined request is left unread
+        BOOST_CHECK(!HTTPRemoteClient::TryReadRequest(client));
+        BOOST_CHECK(!client->GetRequest());
+        BOOST_CHECK_EQUAL(client->GetRecvBuffer().size(), 24);
+    }
+    {
+        // Same, but the socket does not accept data so the closing reply stays
+        // in the send buffer: the pipelined request must still not be read
+        class StalledSock : public ZeroSock
+        {
+        public:
+            ZeroSock& operator=(Sock&&) override { assert(false); return *this; }
+            ssize_t Send(const void*, size_t, int) const override
+            {
+                #ifdef WIN32
+                WSASetLastError(WSAEWOULDBLOCK);
+                #else
+                errno = WSAEAGAIN;
+                #endif
+                return -1;
+            }
+        };
+        class StalledClient : public HTTPRemoteClient
+        {
+        public:
+            StalledClient() : HTTPRemoteClient{/*id=*/0, /*addr=*/CService(), /*socket=*/std::make_unique<StalledSock>()} {}
+            void Receive(std::string_view s) { MutateRecvBuffer().append(s); }
+        };
+        std::shared_ptr<StalledClient> client{std::make_shared<StalledClient>()};
+
+        client->Receive("GET / HTTP/1.0\n\n"
+                        "GET /endpoint HTTP/1.0\n\n");
+        auto req{HTTPRemoteClient::TryReadRequest(client)};
+        BOOST_REQUIRE(req);
+        BOOST_CHECK_EQUAL(client->GetRecvBuffer().size(), 24);
+
+        // The optimistic send fails, the reply is still queued and the client
+        // is not flagged for disconnection yet
+        req->WriteReply(HTTP_OK, "");
+        BOOST_CHECK(client->ReadyToSend());
+
+        BOOST_CHECK(!HTTPRemoteClient::TryReadRequest(client));
+        BOOST_CHECK(!client->GetRequest());
+        BOOST_CHECK_EQUAL(client->GetRecvBuffer().size(), 24);
+    }
     {
         // A Content-Length body is drained out of the receive buffer as it
         // arrives, instead of accumulating there until the request is complete.

